// The full Lucide set as diagram icons (DGM-17, owner scope 2026-11-24). ISC (a few from Feather
// are MIT; icons/LICENSE-lucide.txt). Generated by tools/build-lucide-icons.py:
//   lucide/index.json           names, tags and categories (what search needs), ~42 KB gz
//   lucide/paths/<category>.json path data, each icon in its first category's file
// Both load lazily (their own chunks: not in the initial bundle, not in the board chunk).
//
// A placed Lucide icon stores `props.icon = "lucide:<name>"` and its path data in `props.paths`
// (a few hundred bytes), so the Rust exporter, the preview and other clients draw it without the
// Lucide data. Path data is checked against `PATH_RE` wherever it is read.

export const LUCIDE_PREFIX = "lucide:";
export const PATH_RE = /^[MLHVCSQTAZmlhvcsqtaz0-9 ,.\-]{1,2000}$/;
/** Most paths an embedded icon may carry (Lucide's largest has 15). */
export const MAX_PATHS = 32;

export interface LucideCategory {
  id: string;
  name: string;
  count: number;
}
export interface LucideIndex {
  version: string;
  categories: LucideCategory[];
  /** [name, tags (space separated), category indexes (the first one holds the paths)] */
  icons: [string, string, number[]][];
}

let index: Promise<LucideIndex> | null = null;
/** The Lucide index, loaded once. */
export function loadLucideIndex(): Promise<LucideIndex> {
  index ??= import("./lucide/index.json").then((m) => (m as unknown as { default: LucideIndex }).default ?? (m as unknown as LucideIndex));
  return index;
}

const loaded = new Map<string, Promise<Record<string, string[]>>>();
/** Path data of every icon whose first category is `cat`, loaded once (one chunk per category). */
export function loadCategoryPaths(cat: string): Promise<Record<string, string[]>> {
  let p = loaded.get(cat);
  if (!p) {
    p = /^[a-z-]{1,40}$/.test(cat)
      ? import(`./lucide/paths/${cat}.json`).then((m: { default: Record<string, string[]> }) => m.default).catch(() => ({}))
      : Promise.resolve({});
    loaded.set(cat, p);
  }
  return p;
}

/** Path data of one Lucide icon by name. */
export async function lucidePaths(name: string): Promise<string[] | null> {
  const idx = await loadLucideIndex();
  const row = idx.icons.find((i) => i[0] === name);
  if (!row) return null;
  const paths = (await loadCategoryPaths(idx.categories[row[2][0]].id))[name];
  return paths ?? null;
}

/** "arrow-up-right" → "Arrow up right". */
export const lucideLabel = (name: string) => {
  const s = name.replace(/-/g, " ");
  return s.charAt(0).toUpperCase() + s.slice(1);
};

/** Embedded path data, if it is plain path data within the limits; else null. */
export function readPaths(v: unknown): string[] | null {
  if (!Array.isArray(v) || !v.length || v.length > MAX_PATHS) return null;
  return v.every((d) => typeof d === "string" && PATH_RE.test(d)) ? (v as string[]) : null;
}

export interface LucideHit {
  name: string;
  /** Category index holding the paths. */
  cat: number;
  at?: [number, number];
  tag?: string;
  score: number;
}

/** Search names (prefix, then anywhere) and then tags, best first. */
export function searchLucide(idx: LucideIndex, q: string): LucideHit[] {
  const t = q.trim().toLowerCase();
  if (!t) return [];
  const tq = t.replace(/\s+/g, "-");
  const out: LucideHit[] = [];
  idx.icons.forEach(([name, tags, cats], n) => {
    const i = name.indexOf(tq);
    if (i === 0) out.push({ name, cat: cats[0], at: [0, tq.length], score: n });
    else if (i > 0) out.push({ name, cat: cats[0], at: [i, i + tq.length], score: 10_000 + n });
    else {
      const tag = tags.split(" ").find((w) => w.includes(t)) ?? (tags.includes(t) ? t : undefined);
      if (tag) out.push({ name, cat: cats[0], tag, score: (tag.startsWith(t) ? 20_000 : 30_000) + n });
    }
  });
  return out.sort((a, b) => a.score - b.score);
}
